SELECT p.gender, i.first_careunit, AVG(l.value) AS avg_sbp, COUNT(DISTINCT p.subject_id) AS patient_count FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN chartevents l ON p.subject_id = l.subject_id AND i.stay_id = l.stay_id WHERE p.gender = 'F' AND i.first_careunit = 'ICU' AND l.itemid = 57034001 AND l.charttime BETWEEN i.intime AND i.intime + interval '24 hours' AND p.anchor_year BETWEEN 45 AND 55 GROUP BY p.gender, i.first_careunit, avg_sbp ORDER BY p.gender, i.first_careunit, avg_sbp NULLS LAST;